def diff(a, b):
    w1,h1,c1,p1 = load(a); w2,h2,c2,p2 = load(b)
    if (w1,h1,c1) != (w2,h2,c2):
        return {'geometry': f'{w1}x{h1}x{c1} vs {w2}x{h2}x{c2}'}
    stride = w1*c1; changed = 0; total = 0
    x0,y0,x1,y1 = w1, h1, -1, -1; maxd = 0
    for y in range(h1):
        ro = y*stride
        for x in range(w1):
            o = ro + x*c1
            d = max(abs(p1[o+k]-p2[o+k]) for k in range(min(3,c1)))
            if d:
                changed += 1; total += d; maxd = max(maxd, d)
                if x<x0: x0=x
                if x>x1: x1=x
                if y<y0: y0=y
                if y>y1: y1=y
    return {'size': f'{w1}x{h1}', 'changed_px': changed,
            'pct': round(100*changed/(w1*h1), 3), 'max_delta': maxd,
            'mean_delta_over_changed': round(total/changed, 1) if changed else 0,
            'bbox': None if x1 < 0 else f'x{x0}..{x1} y{y0}..{y1} ({x1-x0+1}x{y1-y0+1})'}

